const mixColor=(from,to,amount)=>{const a=from.match(/[\da-f]{2}/gi).map(v=>parseInt(v,16)),b=to.match(/[\da-f]{2}/gi).map(v=>parseInt(v,16));return '#'+a.map((v,i)=>Math.round(v+(b[i]-v)*amount).toString(16).padStart(2,'0')).join('')};
