function shortTodoDate(date){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(date||''));return m?`${m[2]}/${m[3]}/${m[1].slice(2)}`:''}
function parseTodoDate(value){const m=/^(\d{1,2})\/(\d{1,2})\/(\d{2})$/.exec(String(value||'').trim());if(!m)throw Error('Enter the due date as MM/DD/YY.');const month=Number(m[1]),day=Number(m[2]),year=2000+Number(m[3]),d=new Date(year,month-1,day,12);if(d.getFullYear()!==year||d.getMonth()!==month-1||d.getDate()!==day)throw Error('Enter a valid due date in the 21st century.');return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}
