function toast(message,action,label='Undo'){clearTimeout(toastTimer);const node=$('#toast');node.replaceChildren();const s=document.createElement('span');s.textContent=message;node.append(s);if(action){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{node.classList.remove('show');Promise.resolve(action()).catch(err=>toast(err.message))};node.append(b)}node.classList.add('show');toastTimer=setTimeout(()=>node.classList.remove('show'),6500)}
