function listNodeKey(node){if(node.nodeType!==Node.ELEMENT_NODE)return '';return node.dataset.open?`open:${node.dataset.open}`:node.dataset.id?`id:${node.dataset.id}`:node.id?`dom:${node.id}`:''}
function patchListNode(current,next){if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName){current.replaceWith(next.cloneNode(true));return}if(current.nodeType===Node.TEXT_NODE){if(current.nodeValue!==next.nodeValue)current.nodeValue=next.nodeValue;return}for(const attribute of [...current.attributes])if(!next.hasAttribute(attribute.name))current.removeAttribute(attribute.name);for(const attribute of [...next.attributes])if(current.getAttribute(attribute.name)!==attribute.value)current.setAttribute(attribute.name,attribute.value);patchListChildren(current,next)}
function patchListChildren(current,next){const keyed=new Map([...current.children].map(child=>[listNodeKey(child),child]).filter(([key])=>key));let cursor=current.firstChild;for(const wanted of [...next.childNodes]){let candidate=null,key=listNodeKey(wanted);if(key)candidate=keyed.get(key)||null;if(!candidate&&cursor&&cursor.nodeType===wanted.nodeType&&cursor.nodeName===wanted.nodeName&&!listNodeKey(cursor))candidate=cursor;if(candidate){patchListNode(candidate,wanted);if(candidate!==cursor)current.insertBefore(candidate,cursor);cursor=candidate.nextSibling;if(key)keyed.delete(key)}else{const inserted=wanted.cloneNode(true);current.insertBefore(inserted,cursor)}}while(cursor){const nextSibling=cursor.nextSibling;cursor.remove();cursor=nextSibling}for(const leftover of keyed.values())leftover.remove()}
