const opKey=op=>`${op.collection||'records'}:${op.id}`;
function replaceFailedOps(ops){const keys=new Set(ops.map(opKey));failedOps=failedOps.filter(op=>!keys.has(opKey(op))).concat(ops)}
function clearFailedOps(ops){const keys=new Set(ops.map(opKey));failedOps=failedOps.filter(op=>!keys.has(opKey(op)))}
async function persist(ops,{waitForServer=false}={}){if(!user)throw Error('Sign in to save.');const before=structuredClone(records),oldPhotos=new Map(photos);pending++;lastSyncError='';applyOps(ops);scheduleRender({list:true,detail:true,status:true});let write;try{write=cloud.write(ops)}catch(err){pending--;records=before;photos=oldPhotos;scheduleRender({list:true,detail:true,status:true});throw err}const settled=write.then(()=>{pending--;clearFailedOps(ops);scheduleRender({status:true});return true}).catch(err=>{pending--;replaceFailedOps(ops);applyOps(ops);lastSyncError='Changes could not sync. '+(err.code||err.message);toast('Save rejected. Your edit is still open and can be retried.');scheduleRender({list:true,detail:true,status:true});throw err});if(waitForServer)return settled;settled.catch(()=>{});return {queued:true}}
