function renderList(){if(tab==='settings'||$('#app').hidden)return;if(!loaded){commitList('<p class="loading">Loading your journal…</p>');return}if(tab==='todos'){renderTodos();return}if(tab==='recipes'&&foodView==='ingredients'){renderIngredientList();return}let rows=listType(({recipes:'recipe',notes:'note',cars:'car'})[tab]);if(tab==='notes')rows=rows.filter(r=>!r.encrypted&&(filter==='all'||(filter==='pinned'&&r.pinned)||(filter.startsWith('note:')&&noteCategory(r)===filteredCategory(filter)))).sort((a,b)=>noteUpdatedAt(b).localeCompare(noteUpdatedAt(a))||alpha(a,b));else if(tab==='cars')rows.sort((a,b)=>Number(a.status==='past')-Number(b.status==='past')||String(carOwnershipDate(b)).localeCompare(String(carOwnershipDate(a)))||alpha(a,b));else{if(filter.startsWith('recipe:'))rows=rows.filter(r=>recipeCategory(r)===filteredCategory(filter));rows.sort(byDate)}if(query){const q=query.toLowerCase();rows=rows.filter(r=>tab==='notes'?[r.title,plainRichText(r.body,r.richText)].join('\n').toLowerCase().includes(q):tab==='recipes'?[r.title,...(r.recipeIngredients||[]).map(item=>ingredientName(item.ingredientId))].join('\n').toLowerCase().includes(q):JSON.stringify(r).toLowerCase().includes(q))}
if(!rows.length){const changed=commitList(`<div class="empty"><h2>${query?'No matches':({recipes:'What did you cook?',notes:'Make a little space.',cars:'Your garage starts here.'})[tab]}</h2><p>${query?'Try a different search.':({recipes:'Keep the ingredients, the good bits, and what you’d change next time.',notes:'Keep something useful.',cars:'Add a current car or a car you used to own.'})[tab]}</p>${query?'':'<button class="primary" id="emptyAdd">Add your first entry</button>'}</div>`);if(changed)$('#emptyAdd')?.addEventListener('click',()=>openEditor());return}
commitList(rows.map((r,i)=>{const divider=tab==='cars'&&r.status==='past'&&(i===0||rows[i-1].status!=='past')?'<h2 class="section-label">Previously owned</h2>':'';let meta=tab==='recipes'?[recipeCategory(r),dateLabel(r.date)].filter(Boolean).join(' • '):tab==='notes'?`${noteCategory(r)} • ${noteUpdatedLabel(r)}`:[r.year,r.make,r.model].filter(Boolean).join(' ');const thumb=tab==='recipes'?photoSource(recipeCover(r),'tiny'):r.photos?.map(photo=>photoSource(photo,'tiny')).find(Boolean);if(tab==='cars'){const cover=carCover(r),coverUrl=photoSource(cover,'thumb');return `${divider}<button class="car-card" data-open="${e(r.id)}"><span class="car-card-photo">${coverUrl?`<img src="${e(coverUrl)}" alt="${e(title(r))}" loading="lazy" decoding="async">`:`<span class="car-photo-placeholder">${icon('cars')}<span>Add a cover photo</span></span>`}${r.photos?.length?`<span class="photo-count">${r.photos.length} photo${r.photos.length===1?'':'s'}</span>`:''}</span><span class="car-card-copy"><strong>${e(title(r))}</strong><span>${e(meta)}</span>${r.owner?`<span class="small">${e(r.owner)}</span>`:''}</span></button>`}return `${divider}<button class="band" data-open="${e(r.id)}" style="--band:${PALETTES[tab][Math.min(i,PALETTES[tab].length-1)]}"><span class="copy"><strong>${r.pinned?pinIcon:''}${e(title(r))}</strong><span class="meta">${e(meta)}</span></span>${thumb?`<img class="thumb" src="${e(thumb)}" alt="" loading="lazy" decoding="async">`:''}</button>`}).join(''))}
function renderIngredientList(){let rows=ingredients().filter(item=>!item.hidden);if(query){const q=query.toLowerCase();rows=rows.filter(item=>[item.title,...(item.aliases||[]),...ingredientTagNames(item),plainRichText(item.body,item.richText),item.substitutes||''].join('\n').toLowerCase().includes(q))}if(!rows.length){const changed=commitList(`<div class="empty"><h2>${query?'No matches':'Build your ingredient library.'}</h2><p>${query?'Try a different search.':'Add ingredients once, then reuse them across recipes.'}</p>${query?'':'<button class="primary" id="emptyAdd">Add your first ingredient</button>'}</div>`);if(changed)$('#emptyAdd')?.addEventListener('click',()=>openEditor(null,'ingredient'));return}commitList(`<div class="ingredient-grid">${rows.map(item=>{const cover=ingredientCover(item),coverUrl=photoSource(cover,'thumb'),tags=ingredientTagNames(item);return `<button class="ingredient-card" data-open="${e(item.id)}"><span class="ingredient-card-photo">${coverUrl?`<img src="${e(coverUrl)}" alt="${e(item.title)}" loading="lazy" decoding="async">`:'<span class="ingredient-photo-placeholder">Add photo</span>'}</span><span class="ingredient-card-copy"><strong>${e(item.title)}</strong>${tags.length?`<span>${e(tags.join(' · '))}</span>`:''}</span></button>`}).join('')}</div>`)}
function handleListOpen(event){const list=$('#list'),button=event.target.closest?.('[data-open]');if(!button||!list.contains(button))return;event.preventDefault();event.stopPropagation();const closing=selected===button.dataset.open;selected=closing?null:button.dataset.open;writeViewHistory();list.querySelectorAll('[data-open].selected').forEach(item=>item.classList.remove('selected'));if(!closing)button.classList.add('selected');try{renderDetail()}catch(error){console.error(error);toast('This entry could not be opened. Reload the app and try again.')}if(!closing&&matchMedia('(max-width:680px)').matches)scrollTo(0,0)}
function photoMarkup(items=[],coverPhotoId=''){const ordered=items.map((item,index)=>({item,index}));if(coverPhotoId)ordered.sort((a,b)=>Number(photoKey(b.item)===coverPhotoId)-Number(photoKey(a.item)===coverPhotoId));return ordered.length?`<div class="photos">${ordered.map(({item,index},position)=>{const url=photoSource(item,'detail');return url?`<button class="photo-open" data-photo-index="${index}" style="padding:0;background:none" aria-label="View photo"><img src="${e(url)}" alt="Journal photo" loading="${position?'lazy':'eager'}" decoding="async"></button>`:'<p class="small">Photo is not available offline yet.</p>'}).join('')}</div>`:''}
const RICH_TAGS=new Set(['A','B','BLOCKQUOTE','BR','DIV','LI','OL','P','STRONG','UL']);
function sanitizeRichHTML(value){const template=document.createElement('template');template.innerHTML=String(value||'');const clean=parent=>{for(const child of [...parent.childNodes]){if(child.nodeType===Node.COMMENT_NODE){child.remove();continue}if(child.nodeType!==Node.ELEMENT_NODE)continue;if(!RICH_TAGS.has(child.tagName)){clean(child);child.replaceWith(...child.childNodes);continue}const href=child.tagName==='A'?child.getAttribute('href'):'';for(const attribute of [...child.attributes])child.removeAttribute(attribute.name);if(child.tagName==='A')try{const url=new URL(href);if(!['http:','https:'].includes(url.protocol))throw Error();child.href=url.href;child.target='_blank';child.rel='noopener noreferrer'}catch{child.removeAttribute('href')}clean(child)}};clean(template.content);return template.innerHTML}
function linkifyRichHTML(value){const template=document.createElement('template');template.innerHTML=sanitizeRichHTML(value);const visit=parent=>{for(const child of [...parent.childNodes]){if(child.nodeType===Node.TEXT_NODE&&parent.tagName!=='A'&&/https?:\/\//.test(child.data)){const span=document.createElement('span');span.innerHTML=linkify(child.data);child.replaceWith(...span.childNodes)}else if(child.nodeType===Node.ELEMENT_NODE)visit(child)}};visit(template.content);return template.innerHTML}
function plainRichText(value,formatted=false){if(!formatted)return String(value||'');const node=document.createElement('div');node.innerHTML=sanitizeRichHTML(value);return node.textContent||''}
function reading(label,text,formatted=false){return text?`<h3>${label}</h3><div class="reading ${formatted?'rich-reading':''}">${formatted?linkifyRichHTML(text):linkify(text)}</div>`:''}
function maintenanceHistoryLabel(item){const completed=item.completedDate||item.completedAt?.slice(0,10),scheduled=item.scheduledDate;if(completed&&scheduled)return `Completed ${dateLabel(completed)} · originally due ${dateLabel(scheduled)}`;return completed?`Completed ${dateLabel(completed)}`:dateLabel(item.date)}
function recipeIngredientsMarkup(recipe){const rows=recipe.recipeIngredients||[];if(!rows.length)return '';return `<h3>Ingredients</h3><div class="recipe-ingredients-reading">${rows.map(item=>`<div class="recipe-ingredient-reading"><span class="ingredient-amount">${e(item.amount||'')}</span><button type="button" class="ingredient-link" data-ingredient-link="${e(item.ingredientId)}">${e(ingredientName(item.ingredientId))}</button><span class="ingredient-notes">${e(item.notes||'')}</span></div>`).join('')}</div>`}
function ingredientDetailMarkup(item){const tags=ingredientTagNames(item),linked=recipesUsing(item.id),aliases=(item.aliases||[]).filter(Boolean);return `<p class="sub ingredient-tags">${tags.length?tags.map(tag=>`<span>${e(tag)}</span>`).join(''):'Untagged'}${item.hidden?'<span>Hidden from Ingredients</span>':''}</p>${reading('Cooking notes',item.body,item.richText)}${reading('Substitutes',item.substitutes)}${aliases.length?`<h3>Also known as</h3><p>${e(aliases.join(' · '))}</p>`:''}<h3>Recipes</h3>${linked.length?`<div class="ingredient-recipes">${linked.map(recipe=>{const rows=recipe.recipeIngredients.filter(row=>row.ingredientId===item.id),context=rows.map(row=>[row.amount,row.notes].filter(Boolean).join(' · ')).filter(Boolean).join('; ');return `<button type="button" data-recipe-link="${e(recipe.id)}"><strong>${e(recipe.title)}</strong>${context?`<span>${e(context)}</span>`:''}</button>`}).join('')}</div>`:'<p class="small">No recipes use this ingredient yet.</p>'}`}
function handleDetailFoodNav(event){const ingredient=event.target.closest('[data-ingredient-link]'),recipe=event.target.closest('[data-recipe-link]');if(!ingredient&&!recipe)return;event.preventDefault();event.stopPropagation();foodView=ingredient?'ingredients':'recipes';selected=(ingredient||recipe).dataset[ingredient?'ingredientLink':'recipeLink'];query='';writeViewHistory();render()}
function handleDetailPhoto(event){const button=event.target.closest('[data-photo-index]');if(!button)return;event.preventDefault();event.stopPropagation();showPhoto(selected,Number(button.dataset.photoIndex))}
function sizeDetailTray(){const detail=$('#detail');if(!detail||detail.hidden||!matchMedia('(min-width:681px)').matches){detail?.style.removeProperty('--detail-max-height');return}const viewportHeight=window.visualViewport?.height||window.innerHeight,top=Math.max(120,detail.getBoundingClientRect().top),available=Math.max(120,Math.floor(viewportHeight-top-24));detail.style.setProperty('--detail-max-height',`${available}px`)}
function renderDetail(){
 const detail=$('#detail'),workspace=$('#workspace');
 const r=!['settings','todos'].includes(tab)?get(selected):null;
 const hasDetail=!!r&&!r.deleted&&!(r.type==='note'&&r.encrypted);
 workspace.classList.toggle('show-detail',hasDetail);
 workspace.classList.toggle('browsing',!hasDetail);
 $('main').classList.toggle('recipe-detail',hasDetail&&r.type==='recipe');
 detail.classList.toggle('car-detail',hasDetail&&r.type==='car');
 detail.classList.toggle('ingredient-detail',hasDetail&&r.type==='ingredient');
 detail.classList.remove('blank');
 detail.hidden=!hasDetail;
 if(!hasDetail){detail.replaceChildren();return}
 let body='';if(r.type==='recipe'){body=`<p class="sub">${e(recipeCategory(r))} · ${e(dateLabel(r.date))}</p>${photoMarkup(r.photos,r.coverPhotoId)}${recipeIngredientsMarkup(r)}${reading(r.recipeIngredients?.length?'Legacy ingredients':'Ingredients',r.ingredients,r.richText)}${reading('Method',r.method,r.richText)}${reading('Notes',r.body,r.richText)}`}else if(r.type==='ingredient'){body=ingredientDetailMarkup(r)}else if(r.type==='note'){body=`<p class="sub">${e(noteCategory(r))}</p><div class="reading ${r.richText?'rich-reading':''}">${r.richText?linkifyRichHTML(r.body):linkify(r.body)}</div>`}else if(r.type==='car'){const logs=listType('maintenance').filter(l=>l.carId===r.id).sort(byDate),reminders=listType('reminder').filter(l=>l.carId===r.id&&!l.done).sort((a,b)=>String(a.date||'9999').localeCompare(String(b.date||'9999')));body=`<p class="sub">${e([r.year,r.make,r.model].filter(Boolean).join(' '))}${r.owner?' · '+e(r.owner):''}</p><p class="small car-ownership">${e(carOwnership(r))}</p>${carGallery(r)}${reading('Details',r.body,r.richText)}${r.odometer?`<p>Odometer · ${Number(r.odometer).toLocaleString()} ${e(r.unit||'mi')}</p>`:''}${r.vin?`<p>VIN · ${e(r.vin)}</p>`:''}<h3>Upcoming maintenance</h3>${reminders.length?reminders.map(l=>`<div class="reminder"><button data-child="${e(l.id)}"><b>${e(l.title)}</b><small>${e(dateLabel(l.date)||'No date')}${l.mileage?' · '+Number(l.mileage).toLocaleString()+' '+e(r.unit||'mi'):''}${l.date&&l.date<today?' · Overdue':''}</small></button><button class="text-button" data-reminder-done="${e(l.id)}">Mark done</button></div>`).join(''):'<p class="small">No upcoming maintenance.</p>'}<button class="secondary" id="addReminder">Add reminder</button><h3>Maintenance history</h3>${logs.length?logs.map(l=>`<div class="reminder"><button data-child="${e(l.id)}"><b>${e(l.title)}</b><small>${e(maintenanceHistoryLabel(l))}${l.mileage?' · '+Number(l.mileage).toLocaleString()+' '+e(r.unit||'mi'):''}${l.cost?' · $'+Number(l.cost).toFixed(2):''}</small></button></div>`).join(''):'<p class="small">No maintenance logged yet.</p>'}<button class="secondary" id="addMaintenance">Log maintenance</button>`}
 const hero=r.type==='car'?carHero(r):r.type==='ingredient'?ingredientHero(r):'';
 $('#detail').innerHTML=`${hero}<div class="${r.type==='car'?'car-content':r.type==='ingredient'?'ingredient-content':'entry-content'}"><button class="text-button mobile-back" id="back">‹ Back</button><div class="detail-head"><h2>${e(title(r))}</h2></div>${body}<div class="detail-actions"><button class="secondary" id="editEntry">Edit</button>${r.type==='ingredient'?'<button class="ghost" id="mergeIngredient">Merge</button>':''}${r.type==='note'?`<button class="ghost" id="pinNote">${r.pinned?'Unpin':'Pin note'}</button>`:''}<button class="danger" id="deleteEntry">Delete</button></div></div>`;
 $('#addCarPhotos')?.addEventListener('click',()=>{openEditor(r);$('#photoInput')?.click()});$('#back').onclick=appBack;$('#editEntry')?.addEventListener('click',()=>openEditor(r));$('#deleteEntry').onclick=()=>removeRecord(r);$('#mergeIngredient')?.addEventListener('click',()=>mergeIngredient(r));$('#pinNote')?.addEventListener('click',()=>save({...r,pinned:!r.pinned}));$('#addReminder')?.addEventListener('click',()=>openEditor(null,'reminder',r.id));$('#addMaintenance')?.addEventListener('click',()=>openEditor(null,'maintenance',r.id));$$('[data-child]').forEach(b=>b.onclick=()=>openEditor(get(b.dataset.child)));$$('[data-reminder-done]').forEach(b=>b.onclick=()=>completeCarReminder(get(b.dataset.reminderDone),r.id));requestAnimationFrame(sizeDetailTray)}
async function completeCarReminder(reminder,carId){if(!reminder||reminder.deleted)return;const completedDate=localDate(),scheduledDate=reminder.scheduledDate||reminder.date||'';tab='cars';selected=carId;await save({...reminder,type:'maintenance',date:completedDate,scheduledDate,completedDate,done:true,completedAt:new Date().toISOString()});tab='cars';selected=carId;writeViewHistory(true);renderList();renderDetail()}
function nextScheduleDate(schedule,asOf=localDate()){for(let i=0;i<1200;i++){const date=monthlyDate(schedule.startDate,i*schedule.intervalMonths);if(!date||date>=asOf)return date||''}return ''}
async function cancelSchedule(schedule){if(!schedule||schedule.cancelledOn)return;if(!await ask('Cancel reminder?',`Future “${schedule.title}” To-Dos will stop. To-Dos that have already appeared will remain.`,'Cancel reminder',true))return;await save({...schedule,cancelledOn:localDate()});if(tab==='settings')renderSettings();else renderTodos();toast('Recurring reminder canceled')}
const TODO_MOTION={duration:300,easing:'cubic-bezier(0.37, 0, 0.63, 1)'};
function captureTodoLayout(){const positions=new Map(),states=new Map();for(const wrap of $$('#list .task-wrap[data-id]')){positions.set(wrap.dataset.id,wrap.getBoundingClientRect().top);states.set(wrap.dataset.id,wrap.classList.contains('done'))}return {positions,states}}
function animateTodoLayout(previous){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;for(const wrap of $$('#list .task-wrap[data-id]')){const id=wrap.dataset.id,wasDone=previous.states.get(id),isDone=wrap.classList.contains('done'),label=wrap.querySelector('.task-label>span');if(!reduced&&wasDone===false&&isDone)label?.classList.add('strike-entering');else if(!reduced&&wasDone===true&&!isDone)label?.classList.add('strike-leaving');if(label?.classList.contains('strike-entering')||label?.classList.contains('strike-leaving'))setTimeout(()=>label.classList.remove('strike-entering','strike-leaving'),500);if(reduced||!wrap.animate)continue;const oldTop=previous.positions.get(id),newTop=wrap.getBoundingClientRect().top;if(oldTop!==undefined&&Math.abs(oldTop-newTop)>.5)wrap.animate([{transform:`translateY(${oldTop-newTop}px)`},{transform:'translateY(0)'}],TODO_MOTION);else if(oldTop===undefined&&previous.positions.size)wrap.animate([{opacity:0,transform:'translateY(-8px)'},{opacity:1,transform:'translateY(0)'}],TODO_MOTION)}}
function renderTodos(){
 const previous=captureTodoLayout();
 updateTodoBadge();
 const ordered=done=>listType('todo').filter(t=>!!t.done===done).sort((a,b)=>String(a.date||'9999-12-31').localeCompare(String(b.date||'9999-12-31'))||(a.order||0)-(b.order||0));
 const active=ordered(false),done=ordered(true);
 const slots=todoColorSlots(active);
 const row=t=>{const link=firstTodoLink(t.title),slot=slots.get(t.id),colors=todoRowColors(t.date,slot?.index,slot?.total);return `<li class="task-wrap ${t.done?'done':''}" data-id="${e(t.id)}"><div class="underlay complete"><span>✓ ${t.done?'Restore':'Complete'}</span></div><div class="underlay delete"><span>Delete ×</span></div><div class="task-row" tabindex="0" role="button" aria-label="Edit ${e(t.title)}" style="--band-top:${colors.top};--band-bottom:${colors.bottom}"><div class="task-label">${t.date?`<small>${e(dateLabel(t.date))}${!t.done&&t.date<localDate()?' · Overdue':''}</small>`:''}<span data-text="${e(link.text)}">${linkify(link.text)}</span></div>${link.url?`<a class="todo-web-link" href="${e(link.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open link for ${e(t.title)}">${icon('web')}</a>`:''}</div></li>`};
 const changed=commitList(`<ul class="task-list" aria-label="Active To-Dos">${active.length?active.map(row).join(''):done.length?'':'<li class="empty"><h2>Nothing pressing.</h2><p>Enjoy the blank space.</p></li>'}</ul>${done.length?`<div class="completed-group"><div class="completed-delete-all"><button id="deleteCompleted">Delete all</button></div><ul class="task-list" aria-label="Completed To-Dos">${done.map(row).join('')}</ul></div>`:''}`);
 if(changed){$('#deleteCompleted')?.addEventListener('click',()=>deleteCompleted(done));bindSwipes();animateTodoLayout(previous)}
}
function bindSwipes(){$$('.task-wrap').forEach(wrap=>{
 const row=wrap.querySelector('.task-row'),done=wrap.classList.contains('done'),group=wrap.closest('.completed-group');
 let pointer=null,sx=0,sy=0,dx=0,horizontal=false,moved=false,vertical=false,groupWasOpen=false;
 const threshold=()=>Math.min(160,Math.max(108,wrap.clientWidth*.3));
 const groupRows=()=>[...group.querySelectorAll('.task-row')];
 const settleGroup=open=>{group.classList.remove('swiping-delete-all');group.classList.toggle('delete-open',open);for(const item of groupRows()){item.classList.remove('dragging');item.style.transform=''}};
 const reset=()=>{row.classList.remove('dragging');wrap.classList.remove('swiping-right','swiping-left');row.style.transform=''};
 row.onpointerdown=ev=>{if(ev.target.closest('a')||ev.button!==0)return;pointer=ev.pointerId;sx=ev.clientX;sy=ev.clientY;dx=0;horizontal=moved=vertical=false;groupWasOpen=!!group?.classList.contains('delete-open');row.setPointerCapture?.(pointer)};
 row.onpointermove=ev=>{if(ev.pointerId!==pointer||vertical)return;const x=ev.clientX-sx,y=ev.clientY-sy;if(!horizontal&&Math.abs(y)>8&&Math.abs(y)>Math.abs(x)){vertical=true;moved=true;return}if(!horizontal&&Math.abs(x)>8&&Math.abs(x)>Math.abs(y))horizontal=true;if(!horizontal)return;ev.preventDefault();moved=true;dx=Math.max(-240,Math.min(240,x));if(done&&(groupWasOpen||dx<0)){group.classList.add('swiping-delete-all');const offset=Math.max(-116,Math.min(0,(groupWasOpen?-116:0)+dx));for(const item of groupRows()){item.classList.add('dragging');item.style.transform=`translateX(${offset}px)`}}else{row.classList.add('dragging');row.style.transform=`translateX(${dx}px)`;wrap.classList.toggle('swiping-right',dx>12);wrap.classList.toggle('swiping-left',dx< -12)}};
 row.onpointerup=ev=>{if(ev.pointerId!==pointer)return;pointer=null;const r=get(wrap.dataset.id);if(done&&groupWasOpen){settleGroup(!(dx>30||!moved));return}if(done&&dx<0){settleGroup(-dx>=60);return}if(done&&dx>=threshold()){row.classList.remove('dragging');row.classList.add('completing');navigator.vibrate?.(12);setTimeout(()=>save({...r,done:false}),180);return}if(!done&&Math.abs(dx)>=threshold()){navigator.vibrate?.(12);if(dx>0){row.classList.remove('dragging');row.classList.add('completing');setTimeout(()=>save({...r,done:true}),180)}else{reset();removeTodo(r)}return}reset();if(!moved)openEditor(r)};
 row.onpointercancel=()=>{pointer=null;if(done&&groupWasOpen)settleGroup(true);else if(done&&dx<0)settleGroup(false);else reset()};
 row.onkeydown=ev=>{if(ev.target.closest('a'))return;if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();openEditor(get(wrap.dataset.id))}}
})}
async function removeTodo(r){if(!r?.done&&!await ask('Delete this To-Do?','This To-Do will be permanently deleted.','Delete',true))return false;await save({...r,deleted:true});return true}
async function deleteCompleted(items){if(!items.length)return;const stamp=new Date().toISOString();await persist(items.map(item=>({id:item.id,value:{...item,deleted:true,updatedAt:stamp}})))}
async function ask(title,message,action='Continue',danger=false){const d=$('#confirm');d.innerHTML=`<div class="modal-head"><h2>${e(title)}</h2></div><div class="form-body"><p>${e(message)}</p></div><div class="form-actions"><button id="no" class="ghost">Cancel</button><button id="yes" class="${danger?'danger':'primary'}">${e(action)}</button></div>`;d.showModal();return new Promise(resolve=>{let done=false;const finish=v=>{if(done)return;done=true;d.close();resolve(v)};$('#no').onclick=()=>finish(false);$('#yes').onclick=()=>finish(true);d.oncancel=ev=>{ev.preventDefault();finish(false)}})}
async function removeRecord(r){if(r.type==='ingredient'&&recipesUsing(r.id).length){toast('This ingredient is used by recipes. Hide or merge it instead.');return}if(!await ask('Delete '+(r.type==='car'?'this car':r.type==='note'?'this note':r.type==='ingredient'?'this ingredient':'this entry')+'?',r.type==='car'?'This also removes its maintenance logs and reminders.':'You can undo this immediately after deleting.','Delete',true))return;const related=records.filter(x=>x.id===r.id||(r.type==='car'&&x.carId===r.id));await persist(related.map(x=>({id:x.id,value:{...x,deleted:true}})));selected=null;writeViewHistory(true);renderList();renderDetail();toast('Deleted',()=>persist(related.map(x=>({id:x.id,value:x}))))}
